CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172637_InitialSchemaBaseline') THEN
    CREATE TABLE "Lotes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CodigoLote" text NOT NULL,
        "Fornecedor" text,
        "DataFabricacao" timestamp with time zone,
        "DataValidade" timestamp with time zone,
        "DataEntrada" timestamp with time zone,
        CONSTRAINT "PK_Lotes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172637_InitialSchemaBaseline') THEN
    CREATE TABLE "Usuarios" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "NomeCompleto" text NOT NULL,
        "Email" text NOT NULL,
        "SenhaHash" text NOT NULL,
        "Telefone" text,
        "DataIngresso" timestamp with time zone,
        "NivelUsuario" integer NOT NULL,
        "TipoUsuario" integer NOT NULL,
        "Status" integer NOT NULL,
        "ResponsavelId" integer,
        "TokenRedefinicao" text,
        "TokenExpiracao" timestamp with time zone,
        "Instituicao" text,
        "Cidade" text,
        "Curso" text,
        CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Usuarios_Usuarios_ResponsavelId" FOREIGN KEY ("ResponsavelId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172637_InitialSchemaBaseline') THEN
    CREATE TABLE "Produtos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Catmat" text,
        "NomeProduto" text NOT NULL,
        "Fornecedor" text,
        "Tipo" integer NOT NULL,
        "Quantidade" real NOT NULL,
        "QuantidadeMinima" real NOT NULL,
        "UnidadeMedida" integer NOT NULL,
        "DataFabricacao" timestamp with time zone,
        "DataValidade" timestamp with time zone,
        "LocalizacaoProduto" text,
        "Status" integer NOT NULL,
        "UltimaModificacao" timestamp with time zone NOT NULL,
        "LoteId" integer,
        "EstadoFisico" integer,
        "Cor" integer,
        "Odor" integer,
        "Densidade" real,
        "PesoMolecular" real,
        "GrauPureza" text,
        "FormulaQuimica" text,
        "Grupo" integer,
        "Material" integer,
        "Formato" integer,
        "Altura" integer,
        "Capacidade" real,
        "Graduada" boolean,
        CONSTRAINT "PK_Produtos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Produtos_Lotes_LoteId" FOREIGN KEY ("LoteId") REFERENCES "Lotes" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172637_InitialSchemaBaseline') THEN
    CREATE TABLE "Emprestimos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DataRealizacao" timestamp with time zone NOT NULL,
        "DataDevolucao" timestamp with time zone,
        "DataAprovacao" timestamp with time zone,
        "Status" integer NOT NULL,
        "SolicitanteId" integer NOT NULL,
        "AprovadorId" integer,
        CONSTRAINT "PK_Emprestimos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Emprestimos_Usuarios_AprovadorId" FOREIGN KEY ("AprovadorId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Emprestimos_Usuarios_SolicitanteId" FOREIGN KEY ("SolicitanteId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
