    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172637_InitialSchemaBaseline') THEN
    CREATE TABLE "LogsAuditoria" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DataHora" timestamp with time zone NOT NULL,
        "Acao" character varying(50) NOT NULL,
        "Recurso" character varying(100) NOT NULL,
        "Detalhes" character varying(500),
        "EnderecoIP" character varying(45) NOT NULL,
        "UserAgent" character varying(500),
        "TipoAcao" integer NOT NULL,
        "NivelRisco" integer NOT NULL,
        "Suspeita" boolean NOT NULL,
        "MotivoSuspeita" character varying(1000),
        "UsuarioId" integer,
        "DadosRequisicao" character varying(2000),
        "DadosResposta" character varying(1000),
        "TempoSessao" interval,
        "TentativasAcesso" integer,
        "Origem" character varying(100),
        CONSTRAINT "PK_LogsAuditoria" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_LogsAuditoria_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE SET NULL
    );
    END IF;
END $EF$;

DO $EF$
