        CONSTRAINT "FK_ProdutosEmprestados_Emprestimos_EmprestimoId" FOREIGN KEY ("EmprestimoId") REFERENCES "Emprestimos" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ProdutosEmprestados_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE CASCADE
