DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260830172718_CredentialLifecycle') THEN
    ALTER TABLE "Usuarios" RENAME COLUMN "TokenRedefinicao" TO "TokenRedefinicaoHash";
